    fn next_local_workspace_lifecycle_request_id(&mut self) -> Option<u64> {
        let (request_id, next_request_id) =
            next_available_gpui_local_workspace_lifecycle_request_id(
                self.next_local_workspace_lifecycle_request_id,
                |candidate| {
                    self.local_workspace_lifecycle_requests
                        .contains_key(&candidate)
                },
            )?;
        self.next_local_workspace_lifecycle_request_id = next_request_id;
        Some(request_id)
    }

    fn dispatch_gpui_workspace_terminal_lifecycle_request(
        &mut self,
        message: serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        /*
        CDXC:GPUIWorkspaceLifecycle 2026-06-26-07:25:
        Native GPUI workspace tab lifecycle uses a fixed Rust-to-sidebar callback, not a generic renderer bus. The request contains only request id, action, bounded gxserver project/session ids, and optional replacement ids so the sidebar can perform gxserver lifecycle ownership while Rust keeps pane/tab ownership local.
        */
        let Some(sidebar) = self.sidebar.clone() else {
            return false;
        };
        let script = gpui_workspace_terminal_lifecycle_request_script(&message);
        sidebar.update(cx, |surface, _| surface.execute_app_owned_script(&script))
    }

    #[cfg(target_os = "macos")]
    fn handle_gpui_native_app_shot_capture(
        &mut self,
        capture: GpuiAppShotCapture,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        if self.dispatch_gpui_native_app_shot_capture(capture, cx) {
            return;
        }
        window.push_notification(
            Notification::warning("App Shot captured, but the GPUI sidebar is not ready."),
            cx,
        );
        self.dispatch_gpui_app_modal_toast(
            "warning",
            "App Shot Failed",
            "The GPUI sidebar is not ready to stage the App Shot.",
            cx,
        );
    }

    #[cfg(target_os = "macos")]
    fn dispatch_gpui_native_app_shot_capture(
        &mut self,
        capture: GpuiAppShotCapture,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        /*
        CDXC:GPUIAppShots 2026-06-25-23:28:
        Native Rust owns App Shot capture, path creation, and settings reads. CEF receives only a transient first-party capture payload so the gxserver sidebar runtime can format the macOS-parity prompt, try focused/recent existing-session insertion, or create a prompt-agent session; this capture bridge must not accept renderer-provided screenshot paths, persist capture data, log app/window/path text, or become generic eval IPC.

        CDXC:GPUIAppShots 2026-06-26-04:27:
        Focused/recent App Shot staging may target a remote row only through the separate fixed prompt bridge and an already-mounted remote attach Agents surface. Capture metadata remains first-party and cannot authorize renderer paths, SSH details, URLs, tokens, commands, output, or terminal text.
        */
        let Some(sidebar) = self.sidebar.clone() else {
            return false;
        };
        let mut payload = serde_json::Map::new();
        payload.insert(
            "type".to_string(),
            serde_json::Value::String(GPUI_SIDEBAR_NATIVE_APP_SHOT_MESSAGE_TYPE.to_string()),
        );
        payload.insert(
            "version".to_string(),
            serde_json::json!(GPUI_SIDEBAR_NATIVE_APP_SHOT_MESSAGE_VERSION),
        );
        payload.insert(
            "appName".to_string(),
            serde_json::Value::String(capture.app_name),
        );
        payload.insert(
            "imagePath".to_string(),
            serde_json::Value::String(capture.image_path),
        );
        if let Some(bundle_identifier) = capture.bundle_identifier {
            payload.insert(
                "bundleIdentifier".to_string(),
                serde_json::Value::String(bundle_identifier),
            );
        }
        if let Some(window_title) = capture.window_title {
            payload.insert(
                "windowTitle".to_string(),
                serde_json::Value::String(window_title),
            );
        }
        if let Some(window_width) = capture.window_width {
            payload.insert("windowWidth".to_string(), serde_json::json!(window_width));
        }
        if let Some(window_height) = capture.window_height {
            payload.insert("windowHeight".to_string(), serde_json::json!(window_height));
        }
        if let Some(trigger) = capture.trigger {
            payload.insert("trigger".to_string(), serde_json::Value::String(trigger));
        }
        let script = gpui_native_app_shot_capture_script(&serde_json::Value::Object(payload));
        sidebar.update(cx, |surface, _| surface.execute_app_owned_script(&script))
    }

    fn refresh_sidebar_command_pane_sessions_if_changed(
        &mut self,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        let sessions = self.command_pane.sidebar_command_session_sources(
            self.shell_focus == ShellFocusTarget::CommandPane,
            &self.command_delayed_send_timers,
            &self.command_close_after_done_timers,
            SystemTime::now(),
        );
        let snapshot = sessions.to_string();
        if self.sidebar_command_pane_sessions_snapshot == snapshot {
            return false;
        }
        if !self.dispatch_gpui_sidebar_command_pane_sessions(&sessions, cx) {
            return false;
        }
        self.sidebar_command_pane_sessions_snapshot = snapshot;
        true
    }

    fn refresh_sidebar_agents_delayed_sends_if_changed(
        &mut self,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        self.prune_local_workspace_session_mappings();
        let now_system = SystemTime::now();
        let now_instant = Instant::now();
        let mut sessions = self
            .local_workspace_session_mappings
            .iter()
            .filter_map(|(key, shell_session_id)| {
                let external_session_id =
                    gpui_combined_presentation_session_id(&key.project_id, &key.session_id);
                if let Some(timer) = self
                    .agents_delayed_send_timers
                    .get(shell_session_id)
                    .copied()
                {
                    let remaining_ms = timer.remaining_ms(now_system);
                    return Some(serde_json::json!({
                        "delayedSendDeadlineAt": gpui_iso8601_utc(timer.deadline_at),
                        "delayedSendRemainingLabel":
                            gpui_command_delayed_send_countdown_label(remaining_ms),
                        "delayedSendRemainingMs": remaining_ms,
                        "sessionId": external_session_id,
                    }));
                }
                let watcher = self
                    .agents_send_when_stopped_watchers
                    .get(shell_session_id)?;
                let is_working = self.gpui_agents_send_when_stopped_scope_is_working(
                    *shell_session_id,
                    &watcher.scope,
                )?;
                Some(serde_json::json!({
                    "delayedSendRemainingLabel": gpui_agents_send_when_stopped_remaining_label(
                        watcher,
                        is_working,
                        now_instant,
                    ),
                    "sendWhenAllProjectSessionsStopActive": matches!(
                        &watcher.scope,
                        GpuiAgentsSendWhenStoppedScope::Project(_)
                    ),
                    "sendWhenAgentStopsActive": matches!(
                        &watcher.scope,
                        GpuiAgentsSendWhenStoppedScope::Session
                    ),
                    "sessionId": external_session_id,
                }))
            })
            .collect::<Vec<_>>();
        sessions.sort_by(|left, right| {
            left.get("sessionId")
                .and_then(serde_json::Value::as_str)
                .cmp(&right.get("sessionId").and_then(serde_json::Value::as_str))
        });
        let sessions = serde_json::Value::Array(sessions);
        let snapshot = sessions.to_string();
        if self.sidebar_agents_delayed_sends_snapshot == snapshot {
            return false;
        }
        if !self.dispatch_gpui_sidebar_agents_delayed_sends(&sessions, cx) {
            return false;
        }
        self.sidebar_agents_delayed_sends_snapshot = snapshot;
        true
    }

    /*
    CDXC:SidebarBrowserTabReveal 2026-08-18:
    Record that a newly opened Browser tab should be revealed in the sidebar.
    Only the tab identity is stored; the reveal itself is sent once the tab has
    actually been published to the sidebar, so the sidebar never receives a
    request for a row it cannot resolve. A second open replaces an unsent
    request because only the newest tab is worth revealing.
    */
    fn request_sidebar_browser_tab_reveal(&mut self, tab_id: BrowserTabId) {
        let Some(project_id) = self.browser_tabs_project_id.clone() else {
            return;
        };
        self.pending_sidebar_browser_tab_reveal =
            Some(PendingSidebarBrowserTabReveal { project_id, tab_id });
    }

    fn dispatch_pending_sidebar_browser_tab_reveal(&mut self, cx: &mut gpui::Context<Self>) {
        let Some(pending) = self.pending_sidebar_browser_tab_reveal.take() else {
            return;
        };
        self.sidebar_browser_tab_reveal_request_id =
            self.sidebar_browser_tab_reveal_request_id.wrapping_add(1);
        let request_id = self.sidebar_browser_tab_reveal_request_id;
        let script = gpui_sidebar_reveal_browser_tab_script(&serde_json::json!({
            "projectId": pending.project_id,
            "requestId": request_id,
            "tabId": pending.tab_id.0.to_string(),
        }));
        if let Some(sidebar) = self.sidebar.clone() {
            sidebar.update(cx, |surface, _| surface.execute_app_owned_script(&script));
        }
    }

    fn refresh_gpui_sidebar_browser_tabs_if_changed(
        &mut self,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        let browser_mode_is_visible = self.active_mode == TitlebarMode::Browser
            && self
                .project_editor_shell
                .is_mode_awake(TitlebarMode::Browser);
        let focused_browser_tab_id = if browser_mode_is_visible {
            match self.shell_focus {
                ShellFocusTarget::BrowserPane(pane_id) => {
                    self.browser_tabs.active_tab_id_for_pane(pane_id)
                }
                ShellFocusTarget::BrowserSurface => self
                    .browser_tabs
                    .active_tab_id_for_pane(self.browser_tabs.focused_pane),
                _ => None,
            }
        } else {
            None
        };
        let active_browser_project_id = self.browser_tabs_project_id.clone();
        let active_browser_surface_tab_ids = self
            .browser_surfaces
            .keys()
            .copied()
            .collect::<HashSet<_>>();
        let mut projects = self
            .parked_browser_tabs_by_project
            .iter()
            .filter(|(project_id, _)| self.browser_tabs_project_id.as_ref() != Some(*project_id))
            .map(|(project_id, tabs)| (project_id.as_str(), tabs))
            .collect::<Vec<_>>();
        if let Some(project_id) = self.browser_tabs_project_id.as_deref() {
            projects.push((project_id, &self.browser_tabs));
        }
        projects.sort_by(|left, right| left.0.cmp(right.0));

        let tabs = projects
            .into_iter()
            .flat_map(|(project_id, model)| {
                let project_is_active = active_browser_project_id.as_deref() == Some(project_id);
                let awake_tab_ids = if project_is_active {
                    active_browser_surface_tab_ids.clone()
                } else {
                    HashSet::new()
                };
                let visible_tab_ids = model
                    .rendered_leaf_order()
                    .into_iter()
                    .filter_map(|pane_id| model.active_tab_id_for_pane(pane_id))
                    .collect::<HashSet<_>>();
                /*
                CDXC:GPUIBrowserSidebarSessions 2026-07-12:
                Only loaded tabs project as sidebar browser sessions. The
                address-only "New Tab" placeholder (including the in-place
                reset left behind by closing the last tab) stays out of the
                sidebar, so closing the last browser tab removes its sidebar
                row, and committing an address in the browser address bar
                surfaces the loaded tab as a fresh sidebar session.
                */
                model
                    .tabs
                    .iter()
                    .filter(|tab| tab.state == BrowserTabState::Loaded)
                    .map(move |tab| {
                        serde_json::json!({
                            "isActive": project_is_active && focused_browser_tab_id == Some(tab.id),
                            "isSleeping": !awake_tab_ids.contains(&tab.id),
                            "isVisible": browser_mode_is_visible
                                && project_is_active
                                && visible_tab_ids.contains(&tab.id),
                            "projectId": project_id,
                            "tabId": tab.id.0.to_string(),
                            "faviconUrl": tab
                                .runtime_favicon_fetch
                                .as_ref()
                                .map(|source| source.url.as_str()),
                            "title": tab.display_title(),
                            "url": tab.address_value(),
                        })
                    })
            })
            .collect::<Vec<_>>();
        /*
        CDXC:SidebarBrowserTabReveal 2026-08-18:
        A reveal may only be sent for a tab this snapshot actually carries;
        otherwise the sidebar would be asked to expand and scroll to a row it
        has never been told about. A pending reveal whose tab is missing from a
        published snapshot is dropped, because the tab it named is gone.
        */
        let pending_reveal_is_published =
            self.pending_sidebar_browser_tab_reveal
                .as_ref()
                .is_some_and(|pending| {
                    let pending_tab_id = pending.tab_id.0.to_string();
                    tabs.iter().any(|tab| {
                        tab.get("projectId").and_then(serde_json::Value::as_str)
                            == Some(pending.project_id.as_str())
                            && tab.get("tabId").and_then(serde_json::Value::as_str)
                                == Some(pending_tab_id.as_str())
                    })
                });
        let snapshot = serde_json::Value::Array(tabs).to_string();
        if self.sidebar_browser_tabs_snapshot == snapshot {
            if pending_reveal_is_published {
                self.dispatch_pending_sidebar_browser_tab_reveal(cx);
            }
            return false;
        }
        let Some(sidebar) = self.sidebar.clone() else {
            return false;
        };
        let script = gpui_sidebar_browser_tabs_script(&snapshot);
        if !sidebar.update(cx, |surface, _| surface.execute_app_owned_script(&script)) {
            return false;
        }
        self.sidebar_browser_tabs_snapshot = snapshot;
        if pending_reveal_is_published {
            self.dispatch_pending_sidebar_browser_tab_reveal(cx);
        } else {
            self.pending_sidebar_browser_tab_reveal = None;
        }
        true
    }

    fn refresh_gpui_sidebar_displayed_sessions_if_changed(
        &mut self,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        /*
        CDXC:AutoSleepDisplayedSessions 2026-08-20:
        Auto Sleep ("Sleep idle agent sessions") runs in the sidebar runtime,
        which only knows which rows it last saw selected. That is not the same
        thing as what this shell is rendering: a session switched to Chat view
        parks its terminal behind the chat surface, and a gxserver reconnect
        drops the runtime's local focus/visible sets entirely. Either way an
        idle agent the user is sitting in front of looked retirable.

        Rust is the only party that knows what is on screen, so it publishes
        that set (Agents rendered leaves in Agents mode, companion terminal
        mount slots in the project-editor modes — chat-mode sessions included,
        because the tab still owns its pane) and the sweep protects it. The
        bridge carries bounded local gxserver session ids only: no titles,
        paths, commands, terminal output, or project bodies.
        */
        let session_ids = self
            .gpui_sidebar_visible_local_session_ids()
            .into_iter()
            .filter(|session_id| {
                gpui_sidebar_local_gxserver_session_id_allowed(session_id.as_str())
            })
            .collect::<Vec<_>>();
        let snapshot = serde_json::Value::Array(
            session_ids
                .into_iter()
                .map(serde_json::Value::String)
                .collect(),
        )
        .to_string();
        if self.sidebar_displayed_sessions_snapshot == snapshot {
            return false;
        }
        let Some(sidebar) = self.sidebar.clone() else {
            return false;
        };
        let script = gpui_sidebar_displayed_sessions_script(&snapshot);
        if !sidebar.update(cx, |surface, _| surface.execute_app_owned_script(&script)) {
            return false;
        }
        self.sidebar_displayed_sessions_snapshot = snapshot;
        true
    }

    fn dispatch_gpui_sidebar_command_pane_sessions(
        &mut self,
        sessions: &serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        /*
        CDXC:GPUICommandPane 2026-06-25-10:50:
        Command-pane session indicators use a dedicated first-party sidebar bridge callback and cached `window.ghostexGpui.commandPaneSessions` value so restored tabs can hydrate before React installs listeners. The script may carry only sanitized session summaries, never action command text, cwd, env, status-file paths, terminal output, or project paths.
        */
        let Some(sidebar) = self.sidebar.clone() else {
            return false;
        };
        let script = gpui_sidebar_command_pane_sessions_script(sessions);
        sidebar.update(cx, |surface, _| surface.execute_app_owned_script(&script))
    }

    fn dispatch_gpui_sidebar_agents_delayed_sends(
        &mut self,
        sessions: &serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        let Some(sidebar) = self.sidebar.clone() else {
            return false;
        };
        let script = gpui_sidebar_agents_delayed_sends_script(sessions);
        sidebar.update(cx, |surface, _| surface.execute_app_owned_script(&script))
    }

    fn dispatch_gpui_sidebar_command_run_state(
        &mut self,
        command_id: &str,
        run_id: &str,
        state: GpuiSidebarCommandRunState,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        self.sidebar_command_run_feedback_states
            .entry(command_id.to_string())
            .or_default()
            .apply_run_state(run_id, state);
        self.dispatch_gpui_sidebar_host_message(
            serde_json::json!({
                "commandId": command_id,
                "runId": run_id,
                "state": state.as_str(),
                "type": "sidebarCommandRunStateChanged",
            }),
            cx,
        )
    }

    fn dispatch_gpui_sidebar_command_run_state_cleared(
        &mut self,
        command_id: &str,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        self.sidebar_command_run_feedback_states.remove(command_id);
        self.dispatch_gpui_sidebar_host_message(
            serde_json::json!({
                "commandId": command_id,
                "type": "sidebarCommandRunStateCleared",
            }),
            cx,
        )
    }

    fn dispatch_gpui_command_action_completions(
        &mut self,
        completions: Vec<CommandPaneActionRunCompletion>,
        cx: &mut gpui::Context<Self>,
    ) {
        for completion in completions {
            self.dispatch_gpui_sidebar_command_run_state(
                &completion.command_id,
                &completion.run_id,
                completion.run_state(),
                cx,
            );
            if let Some(action) =
                gpui_project_board_action_for_command_id(completion.command_id.as_str())
            {
                self.dispatch_gpui_project_board_command_completed(
                    action,
                    completion.exit_code,
                    cx,
                );
            }
            if completion.should_play_completion_sound() {
                let _ = gpui_play_completion_sound(gpui_action_completion_sound_from_settings());
            }
            /*
            CDXC:GPUIDesktopControlSettings 2026-08-09:
            Cua Driver install/update runs as a normal command Action, so its
            exit is the only honest completion signal. Complete the bundled
            Ghostex Computer Use skill step and refresh Settings from that exit
            code instead of guessing while the command is still running.
            */
            let cua_driver_update = match completion.command_id.as_str() {
                GPUI_CUA_DRIVER_INSTALL_COMMAND_ID => Some(false),
                GPUI_CUA_DRIVER_UPDATE_COMMAND_ID => Some(true),
                _ => None,
            };
            if let Some(was_update) = cua_driver_update {
                self.run_gpui_ghostex_cli_settings_action(
                    GpuiGhostexCliSettingsAction::FinishDesktopControlSetup {
                        driver_installed: completion.exit_code == 0,
                        was_update,
                    },
                    cx,
                );
            }
            self.close_completed_gpui_command_action_tab_if_requested(&completion, cx);
        }
    }

    fn close_completed_gpui_command_action_tab_if_requested(
        &mut self,
        completion: &CommandPaneActionRunCompletion,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        /*
        CDXC:GPUICommandPaneActions 2026-06-26-04:59:
        Native command-pane Actions keep completed tabs reusable even when older Action definitions requested close-on-exit. Keep this completion close helper as a stale-record guard only; current runtime completions normalize close-on-exit to false and must not remove the Action-owned command tab after sidebar feedback.
        */
        let Some(completed_tab) = self.command_pane.close_completed_action_run_tab(completion)
        else {
            return false;
        };
        self.forget_command_gxserver_session_for_closed_tab(completed_tab.session_id, cx);
        self.prune_gpui_command_delayed_send_timers_for_command_model();
        self.prune_gpui_command_close_after_done_timers_for_command_model();
        if self.command_pane.has_sessions() {
            self.focus_command_pane();
        } else {
            self.restore_previous_non_command_focus_or_default();
        }
        self.scroll_command_group_active_tab(completed_tab.group_id);
        self.scroll_focused_command_active_tab();
        self.persist_shell_layout_state();
        self.sync_gpui_keep_awake_automation_from_current_settings(cx);
        self.refresh_sidebar_command_pane_sessions_if_changed(cx);
        cx.notify();
        true
    }

    fn close_gpui_sidebar_command_run(
        &mut self,
        command_id: &str,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        /*
        CDXC:GPUICommandPane 2026-06-25-10:34:
        Ending a sidebar command run closes only the live command-pane Action tab mapped to that command id and clears sidebar button feedback. The tab is removed from the command-pane model immediately (macOS command close parity); render reconciliation drops any mounted surface. This path must not inspect command text, terminal output, titles, status-file contents, paths, URLs, or persisted shell JSON.
        */
        let slot = self
            .command_pane
            .take_action_session_slot_for_action_close(command_id);
        self.dispatch_gpui_sidebar_command_run_state_cleared(command_id, cx);
        let Some(slot) = slot else {
            cx.notify();
            return false;
        };
        let slot = CommandTerminalBodyMountSlotId {
            group_id: slot.0,
            session_id: slot.1,
        };
        self.clear_gpui_command_delayed_send_timer(slot.session_id);
        self.clear_gpui_command_close_after_done_timer(slot.session_id);
        if !self
            .command_pane
            .close_session(slot.group_id, slot.session_id)
        {
            cx.notify();
            return false;
        }
        self.forget_command_gxserver_session_for_closed_tab(slot.session_id, cx);
        self.clear_command_resize_hover_state_if_command_pane_hidden();
        if self.command_pane.has_sessions() {
            self.focus_command_pane();
        } else {
            self.restore_previous_non_command_focus_or_default();
        }
        self.scroll_command_group_active_tab(slot.group_id);
        self.scroll_focused_command_active_tab();
        self.persist_shell_layout_state();
        self.sync_gpui_keep_awake_automation_from_current_settings(cx);
        self.refresh_sidebar_command_pane_sessions_if_changed(cx);
        cx.notify();
        true
    }

    fn sleep_project_editor_mode_from_timer(
        &mut self,
        mode: TitlebarMode,
        token: u64,
        cx: &mut gpui::Context<Self>,
    ) {
        if self.project_editor_auto_sleep_epochs.epoch(mode) != Some(token)
            || self.active_mode == mode
            || !self.project_editor_shell.is_mode_awake(mode)
        {
            return;
        }

        if !self.project_editor_shell.mark_mode_sleeping(mode) {
            return;
        }
        self.project_editor_auto_sleep_epochs.bump(mode);
        if mode == TitlebarMode::Browser {
            self.update_active_mode_cef_child_visibility(cx);
        }
        if mode == TitlebarMode::Source {
            /*
            macOS `stopCodeServerRuntimeIfEveryEditorSleeping` parity: when the
            last awake Source surface sleeps, the shared code-server process
            exits instead of idling hidden. GPUI's single workspace window has
            exactly one Source surface, so Source-mode sleep IS "every editor
            sleeping"; the click-to-wake path relaunches the runtime through
            the existing ensure/start pipeline.
            */
            self.stop_source_code_server_runtime(cx);
        }
        self.persist_shell_layout_state();
        cx.notify();
    }

    fn reconcile_browser_address_inputs(&mut self) {
        let pane_ids = self
            .browser_tabs
            .rendered_leaf_order()
            .into_iter()
            .collect::<HashSet<_>>();
        self.browser_address_inputs
            .retain(|pane_id, _| pane_ids.contains(pane_id));
        self.browser_address_input_subscriptions
            .retain(|pane_id, _| pane_ids.contains(pane_id));
        self.browser_address_input_editing
            .retain(|pane_id| pane_ids.contains(pane_id));
        if self
            .pending_browser_address_focus
            .is_some_and(|pane_id| !pane_ids.contains(&pane_id))
        {
            self.pending_browser_address_focus = None;
        }
        if self
            .pending_browser_content_focus
            .is_some_and(|pane_id| !pane_ids.contains(&pane_id))
        {
            self.pending_browser_content_focus = None;
        }
    }

    fn sync_browser_address_inputs(&mut self, window: &mut Window, cx: &mut gpui::Context<Self>) {
        let pane_ids = self.browser_tabs.rendered_leaf_order();
        let pane_id_set = pane_ids.iter().copied().collect::<HashSet<_>>();
        self.browser_address_inputs
            .retain(|pane_id, _| pane_id_set.contains(pane_id));
        self.browser_address_input_subscriptions
            .retain(|pane_id, _| pane_id_set.contains(pane_id));
        self.browser_address_input_editing
            .retain(|pane_id| pane_id_set.contains(pane_id));
        if self
            .pending_browser_address_focus
            .is_some_and(|pane_id| !pane_id_set.contains(&pane_id))
        {
            self.pending_browser_address_focus = None;
        }
        if self
            .pending_browser_content_focus
            .is_some_and(|pane_id| !pane_id_set.contains(&pane_id))
        {
            self.pending_browser_content_focus = None;
        }

        for pane_id in pane_ids {
            let address_value = self.browser_tabs.address_value_for_pane(pane_id);
            if self.browser_address_inputs.contains_key(&pane_id) {
                if !self.browser_address_input_editing.contains(&pane_id) {
                    self.set_browser_address_input_value_unchecked(
                        pane_id,
                        address_value,
                        window,
                        cx,
                    );
                }
                continue;
            }
            let input = cx.new(|cx| {
                InputState::new(window, cx)
                    .placeholder("Search or enter address")
                    .default_value(&address_value)
            });
            let subscription = cx.subscribe(
                &input,
                move |this: &mut Self, input, event: &InputEvent, cx| match event {
                    InputEvent::Focus | InputEvent::Change => {
                        this.browser_address_input_editing.insert(pane_id);
                    }
                    InputEvent::Blur => {
                        this.browser_address_input_editing.remove(&pane_id);
                    }
                    InputEvent::PressEnter { .. } => {
                        this.browser_address_input_editing.remove(&pane_id);
                        if let Some(url) = normalize_address(input.read(cx).value().as_ref()) {
                            this.commit_browser_address_for_pane(pane_id, url, cx);
                        } else {
                            this.request_browser_content_focus(pane_id);
                            cx.notify();
                        }
                    }
                },
            );
            self.browser_address_inputs.insert(pane_id, input);
            self.browser_address_input_subscriptions
                .insert(pane_id, subscription);
        }

        self.drain_pending_browser_address_focus(window, cx);
        self.drain_pending_browser_content_focus(window, cx);
    }

    fn start_find_in_focused_browser(
        &mut self,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        let ShellFocusTarget::BrowserPane(pane_id) = self.shell_focus else {
            return false;
        };
        if self.active_mode != TitlebarMode::Browser {
            return false;
        }
        let Some((tab_id, _, _)) = self.active_loaded_browser_tab_for_pane(pane_id) else {
            return false;
        };
        self.ensure_browser_surface_for_pane(pane_id, cx);
        self.browser_find_states.entry(tab_id).or_default();
        self.pending_browser_address_focus = None;
        self.pending_browser_content_focus = None;
        self.pending_browser_find_focus = Some(tab_id);
        self.sync_browser_find_inputs(window, cx);
        cx.notify();
        true
    }

    fn perform_browser_find_navigation(
        &mut self,
        tab_id: BrowserTabId,
        forward: bool,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        let Some(query) = self
            .browser_find_states
            .get(&tab_id)
            .map(|find| find.query.trim().to_string())
            .filter(|query| !query.is_empty())
        else {
            return false;
        };
        let Some(surface) = self.browser_surfaces.get(&tab_id).cloned() else {
            return false;
        };
        surface.update(cx, |surface, _| {
            surface.find_text(&query, forward, true);
        });
        true
    }

    fn handle_browser_find_input_event(
        &mut self,
        tab_id: BrowserTabId,
        input: &Entity<InputState>,
        event: &InputEvent,
        cx: &mut gpui::Context<Self>,
    ) {
        match event {
            InputEvent::Change => {
                let query = input.read(cx).value().to_string();
                let Some(find) = self.browser_find_states.get_mut(&tab_id) else {
                    return;
                };
                find.query = query.clone();
                find.match_count = 0;
                find.active_match_ordinal = 0;
                find.final_update = false;
                if let Some(surface) = self.browser_surfaces.get(&tab_id).cloned() {
                    surface.update(cx, |surface, _| {
                        if query.trim().is_empty() {
                            surface.stop_finding(true);
                        } else {
                            surface.find_text(&query, true, false);
                        }
                    });
                }
                cx.notify();
            }
            InputEvent::PressEnter { shift, .. } => {
                let _ = self.perform_browser_find_navigation(tab_id, !*shift, cx);
            }
            InputEvent::Focus | InputEvent::Blur => {}
        }
    }

    fn sync_browser_find_inputs(&mut self, window: &mut Window, cx: &mut gpui::Context<Self>) {
        let live_tab_ids = self
            .browser_tabs
            .tabs
            .iter()
            .map(|tab| tab.id)
            .collect::<HashSet<_>>();
        self.browser_find_states
            .retain(|tab_id, _| live_tab_ids.contains(tab_id));
        self.browser_find_inputs
            .retain(|tab_id, _| self.browser_find_states.contains_key(tab_id));
        self.browser_find_input_subscriptions
            .retain(|tab_id, _| self.browser_find_states.contains_key(tab_id));

        let active_finds = self
            .browser_find_states
            .iter()
            .map(|(tab_id, find)| (*tab_id, find.query.clone()))
            .collect::<Vec<_>>();
        for (tab_id, query) in active_finds {
            if self.browser_find_inputs.contains_key(&tab_id) {
                continue;
            }
            let input = cx.new(|cx| {
                InputState::new(window, cx)
                    .placeholder("Find in page")
                    .default_value(&query)
            });
            let subscription = cx.subscribe(
                &input,
                move |this: &mut Self, input, event: &InputEvent, cx| {
                    this.handle_browser_find_input_event(tab_id, &input, event, cx);
                },
            );
            self.browser_find_inputs.insert(tab_id, input);
            self.browser_find_input_subscriptions
                .insert(tab_id, subscription);
        }

        if let Some(tab_id) = self.pending_browser_find_focus.take()
            && let Some(input) = self.browser_find_inputs.get(&tab_id).cloned()
        {
            #[cfg(any(target_os = "macos", target_os = "windows"))]
            cef::focus_gpui_root_view(self.parent_ns_view);
            input.update(cx, |input, cx| input.focus(window, cx));
        }
    }

    fn close_browser_find(
        &mut self,
        tab_id: BrowserTabId,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        if let Some(surface) = self.browser_surfaces.get(&tab_id).cloned() {
            surface.update(cx, |surface, _| surface.stop_finding(true));
        }
        self.browser_find_states.remove(&tab_id);
        self.browser_find_inputs.remove(&tab_id);
        self.browser_find_input_subscriptions.remove(&tab_id);
        if self.pending_browser_find_focus == Some(tab_id) {
            self.pending_browser_find_focus = None;
        }
        if let Some(pane_id) = find_browser_leaf_id_for_tab(&self.browser_tabs.root, tab_id) {
            self.focus_browser_content_for_pane(pane_id, window, cx);
        }
        cx.notify();
    }

    fn browser_find_input_owns_keyboard_focus(&self, window: &Window, cx: &App) -> bool {
        self.browser_find_inputs
            .values()
            .any(|input| input.read(cx).focus_handle(cx).is_focused(window))
    }

    fn perform_focused_cef_pane_zoom(
        &mut self,
        command: GpuiFocusedSurfaceZoomCommand,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        /*
        CDXC:GPUICefPaneZoomShortcuts 2026-07-14:
        Cmd+=, Cmd+-, and Cmd+0 belong to the exact focused main CEF pane,
        not only Browser tabs. Source, Kanban, Automate, and Docs use the
        same Chromium host zoom API as Browser while sidebar, modal,
        titlebar, and companion CEF surfaces remain outside this command.
        Resolve only from shell focus plus the active mode and an existing
        owned surface; never infer a target or create a fallback surface.
        */
        let surface = match self.shell_focus {
            ShellFocusTarget::BrowserPane(pane_id) if self.active_mode == TitlebarMode::Browser => {
                self.browser_surface_for_pane(pane_id)
            }
            ShellFocusTarget::ProjectEditorSurface(mode) if self.active_mode == mode => {
                let slot_key = match mode {
                    TitlebarMode::Source => ProjectWorkareaCefSurfaceSlotKey::Source,
                    TitlebarMode::Kanban => ProjectWorkareaCefSurfaceSlotKey::Kanban,
                    TitlebarMode::Automate => ProjectWorkareaCefSurfaceSlotKey::Automate,
                    TitlebarMode::Manage => ProjectWorkareaCefSurfaceSlotKey::Manage,
                    TitlebarMode::Agents | TitlebarMode::Browser => return false,
                };
                self.project_workarea_runtime_cef_surface_for_render(slot_key)
            }
            _ => return false,
        };
        let Some(surface) = surface else {
            return false;
        };
        surface.update(cx, |surface, _| match command {
            GpuiFocusedSurfaceZoomCommand::In => surface.zoom_in(),
            GpuiFocusedSurfaceZoomCommand::Out => surface.zoom_out(),
            GpuiFocusedSurfaceZoomCommand::Reset => surface.reset_zoom(),
        });
        cx.notify();
        true
    }

    fn perform_focused_surface_zoom(
        &mut self,
        command: GpuiFocusedSurfaceZoomCommand,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        /*
        Focused-surface zoom keeps the existing CEF behavior and gives the
        composited terminal engine the same shortcuts. Terminal zoom is local
        to the exact focused live view: it does not persist Settings, recreate
        the process, or resize sibling terminals. Cmd+0 returns that view to
        the size derived from its most recently applied terminal config.
        */
        if self.perform_focused_cef_pane_zoom(command, cx) {
            return true;
        }

        let Some(view) = self.focused_gpui_engine_terminal_view() else {
            return false;
        };
        view.update(cx, |view, cx| {
            let changed = match command {
                GpuiFocusedSurfaceZoomCommand::In => view.adjust_font_size(
                    TERMINAL_FONT_ZOOM_STEP,
                    shared_settings::MIN_TERMINAL_FONT_SIZE,
                    shared_settings::MAX_TERMINAL_FONT_SIZE,
                ),
                GpuiFocusedSurfaceZoomCommand::Out => view.adjust_font_size(
                    -TERMINAL_FONT_ZOOM_STEP,
                    shared_settings::MIN_TERMINAL_FONT_SIZE,
                    shared_settings::MAX_TERMINAL_FONT_SIZE,
                ),
                GpuiFocusedSurfaceZoomCommand::Reset => view.reset_font_size(),
            };
            if changed {
                cx.notify();
            }
        });
        true
    }

    fn set_browser_address_input_value(
        &mut self,
        pane_id: BrowserPaneId,
        value: String,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        if self.browser_address_input_editing.contains(&pane_id) {
            return;
        }
        self.set_browser_address_input_value_unchecked(pane_id, value, window, cx);
    }

    fn set_browser_address_input_value_unchecked(
        &mut self,
        pane_id: BrowserPaneId,
        value: String,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        if let Some(input) = self.browser_address_inputs.get(&pane_id).cloned() {
            let value_changed = input.read(cx).value().as_ref() != value.as_str();
            if value_changed {
                input.update(cx, |input, cx| input.set_value(value, window, cx));
            }
        }
    }

    fn request_browser_address_focus(
        &mut self,
        pane_id: BrowserPaneId,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        self.pending_browser_content_focus = None;
        self.pending_browser_address_focus = Some(pane_id);
        self.browser_address_input_editing.remove(&pane_id);
        let address_value = self.browser_tabs.address_value_for_pane(pane_id);
        self.set_browser_address_input_value_unchecked(pane_id, address_value, window, cx);
        self.drain_pending_browser_address_focus(window, cx);
    }

    fn drain_pending_browser_address_focus(
        &mut self,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(pane_id) = self.pending_browser_address_focus else {
            return;
        };
        if self.focus_browser_address_input_for_pane(pane_id, window, cx) {
            self.pending_browser_address_focus = None;
        }
    }

    fn focus_browser_address_input_for_pane(
        &mut self,
        pane_id: BrowserPaneId,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        if !self.titlebar_mode_available(TitlebarMode::Browser)
            || !self.browser_tabs.focus_pane(pane_id)
        {
            return false;
        }
        let Some(input) = self.browser_address_inputs.get(&pane_id).cloned() else {
            return false;
        };

        self.active_mode = TitlebarMode::Browser;
        self.mark_project_editor_mode_awake(TitlebarMode::Browser, cx);
        self.set_shell_focus(ShellFocusTarget::BrowserPane(pane_id));
        self.browser_address_input_editing.insert(pane_id);
        #[cfg(any(target_os = "macos", target_os = "windows"))]
        cef::focus_gpui_root_view(self.parent_ns_view);
        input.update(cx, |input, cx| input.focus(window, cx));
        true
    }

    fn request_browser_content_focus(&mut self, pane_id: BrowserPaneId) {
        self.pending_browser_address_focus = None;
        self.pending_browser_content_focus = Some(pane_id);
        self.browser_address_input_editing.remove(&pane_id);
    }

    fn drain_pending_browser_content_focus(
        &mut self,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(pane_id) = self.pending_browser_content_focus.take() else {
            return;
        };
        self.focus_browser_content_for_pane(pane_id, window, cx);
    }

    fn focus_browser_content_for_pane(
        &mut self,
        pane_id: BrowserPaneId,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        if !self.titlebar_mode_available(TitlebarMode::Browser)
            || !self.browser_tabs.focus_pane(pane_id)
        {
            return false;
        }

        self.active_mode = TitlebarMode::Browser;
        self.mark_project_editor_mode_awake(TitlebarMode::Browser, cx);
        self.set_shell_focus(ShellFocusTarget::BrowserPane(pane_id));
        if let Some(surface) = self.browser_surface_for_pane(pane_id) {
            let focus_handle = surface.read(cx).focus_handle.clone();
            focus_handle.focus(window, cx);
            surface.update(cx, |surface, _| surface.focus());
        } else {
            window.blur();
        }
        true
    }

    fn cancel_browser_address_edit_for_pane(
        &mut self,
        pane_id: BrowserPaneId,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        if self.browser_tabs.find_leaf(pane_id).is_none() {
            return;
        }
        let address_value = self.browser_tabs.address_value_for_pane(pane_id);
        self.browser_address_input_editing.remove(&pane_id);
        self.pending_browser_address_focus = None;
        self.set_browser_address_input_value_unchecked(pane_id, address_value, window, cx);
        self.focus_browser_content_for_pane(pane_id, window, cx);
        cx.notify();
    }

    fn commit_browser_address(&mut self, url: String, cx: &mut gpui::Context<Self>) {
        self.commit_browser_address_for_pane(self.browser_tabs.focused_pane, url, cx);
    }

    fn commit_browser_address_for_pane(
        &mut self,
        pane_id: BrowserPaneId,
        url: String,
        cx: &mut gpui::Context<Self>,
    ) {
        if !self.titlebar_mode_available(TitlebarMode::Browser) {
            return;
        }
        self.browser_url = url.clone();
        self.mark_project_editor_mode_awake(TitlebarMode::Browser, cx);
        /*
        CDXC:SidebarBrowserTabReveal 2026-08-18:
        Committing an address in an address-only "New Tab" is the moment that
        tab first becomes a sidebar row (placeholders are deliberately not
        projected as browser sessions), so it is a new tab as far as the sidebar
        is concerned and gets the same reveal as any other new tab. Navigating
        an already-loaded tab is not.
        */
        let was_address_only_tab = self
            .browser_tabs
            .active_tab_for_pane(pane_id)
            .is_some_and(|tab| tab.state != BrowserTabState::Loaded);
        let Some((committed_tab_id, _profile_id)) = self
            .browser_tabs
            .load_pane_active_tab_url(pane_id, url.clone())
        else {
            return;
        };
        if was_address_only_tab {
            self.request_sidebar_browser_tab_reveal(committed_tab_id);
        }
        self.browser_tabs.focus_pane(pane_id);
        self.set_shell_focus(ShellFocusTarget::BrowserPane(pane_id));
        self.load_browser_cef_url_for_pane(pane_id, &url, cx);
        self.request_browser_content_focus(pane_id);
        self.persist_shell_layout_state();
        cx.notify();
    }

    fn active_loaded_browser_tab_for_pane(
        &self,
        pane_id: BrowserPaneId,
    ) -> Option<(BrowserTabId, String, BrowserProfileId)> {
        self.browser_tabs
            .active_tab_for_pane(pane_id)
            .filter(|tab| tab.state == BrowserTabState::Loaded)
            .map(|tab| (tab.id, tab.cef_url(), tab.profile_id))
    }

    fn browser_surface_for_pane(&self, pane_id: BrowserPaneId) -> Option<Entity<CefSurface>> {
        if !self.browser_surfaces_may_be_visible() {
            return None;
        }

        self.browser_tabs
            .active_tab_for_pane(pane_id)
            .filter(|tab| tab.state == BrowserTabState::Loaded)
            .and_then(|tab| self.browser_surfaces.get(&tab.id).cloned())
    }

    fn browser_surfaces_may_be_visible(&self) -> bool {
        self.browser_runtime_lifecycle_input()
            .allows_cef_child_views()
    }

    fn browser_surface_for_rendered_leaf(&self, leaf: &BrowserLeaf) -> Option<Entity<CefSurface>> {
        /*
        CDXC:GPUIBrowserSplits 2026-06-22-09:55:
        Browser body rendering may attach an existing tab-owned CEF entity for every rendered split leaf whose active tab is loaded, but rendering must never materialize a restored or inactive tab. Missing loaded CEF entities return no surface so the body renderer can show the restored/sleeping placeholder card, address-only tabs stay blank, and Browser sleep, non-Browser modes, Browser tab drags, and command-tab drags hide every surface.
        */
        if !self.browser_surfaces_may_be_visible() {
            return None;
        }

        let tab_id = self.browser_tabs.active_loaded_tab_id_for_leaf(leaf)?;
        self.browser_surfaces.get(&tab_id).cloned()
    }

    fn browser_runtime_lifecycle_input(&self) -> BrowserRuntimeLifecycleInput {
        BrowserRuntimeLifecycleInput {
            active_mode: self.active_mode,
            browser_awake: self
                .project_editor_shell
                .is_mode_awake(TitlebarMode::Browser),
            browser_tab_drag_active: self.browser_tab_drag_active,
            command_tab_drag_active: self.command_tab_drag_active,
            workspace_tab_drag_active: self.workspace_tab_drag_active,
        }
    }

    fn ensure_browser_surface_for_tab(
        &mut self,
        tab_id: BrowserTabId,
        url: String,
        profile_id: BrowserProfileId,
        cx: &mut gpui::Context<Self>,
    ) -> Option<Entity<CefSurface>> {
        if let Some(surface) = self.browser_surfaces.get(&tab_id) {
            return Some(surface.clone());
        }

        let parent_ns_view = self.parent_ns_view;
        let surface_id = format!("gpui-browser-tab-{}", tab_id.0);
        /*
        CDXC:GPUIBrowserProfiles 2026-06-23-11:14:
        CEF Browser surfaces must be keyed by tab id for runtime ownership but created with the tab's generated Browser profile id. This lets existing loaded surfaces keep their profile after toolbar selection changes while future tabs/surfaces use the newly selected profile.
        */
        let profile = profile_id.cef_profile_string();
        let popup_open_handler = self.browser_popup_open_handler(cx);
        let page_metadata_handler = self.browser_page_metadata_handler(tab_id, cx);
        let media_access_handler = self.browser_media_access_handler(tab_id, profile_id, cx);
        let initially_visible = BrowserRuntimeSurfacePolicy::for_tab(
            self.browser_runtime_lifecycle_input(),
            self.browser_tabs.tab(tab_id).map(|tab| tab.state),
            self.browser_tabs
                .rendered_active_loaded_tab_ids()
                .contains(&tab_id),
            true,
        )
        .shows_cef_child_view();
        let surface = match CefSurface::try_new(
            surface_id,
            parent_ns_view,
            url,
            profile,
            CEF_DARK_PREPAINT_BACKGROUND_COLOR,
            true,
            rgb(0xFFFFFF).into(),
            None,
            initially_visible,
            Some(popup_open_handler),
            Some(page_metadata_handler),
            Some(media_access_handler),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            cx,
        ) {
            Ok(surface) => surface,
            Err(error) => {
                // Ensure-style reconcile: skip this pass, retried the next
                // time the tab needs a surface
                // (CDXC:GPUICefBrowserCreateFallible 2026-07-11).
                support_logs::append(
                    support_logs::GpuiSupportLog::CrashReports,
                    "gpui.cefSurface.createFailed",
                    serde_json::json!({ "surface": "browserTab", "error": error }),
                );
                return None;
            }
        };
        self.browser_surfaces.insert(tab_id, surface.clone());
        Some(surface)
    }

    fn browser_popup_open_handler(
        &self,
        cx: &mut gpui::Context<Self>,
    ) -> cef::BrowserPopupOpenHandler {
        let app = cx.entity().downgrade();
        let async_cx = cx.to_async();
        let foreground = cx.foreground_executor().clone();
        let project_epoch = self.browser_tabs_project_epoch;

        Rc::new(
            move |requested_url: String, placement: cef::BrowserPopupPlacement| {
                let app = app.clone();
                let mut async_cx = async_cx.clone();
                foreground
                    .spawn(async move {
                        let _ = app.update_in(&mut async_cx, |this, window, cx| {
                            if this.browser_tabs_project_epoch != project_epoch {
                                return;
                            }
                            this.open_browser_popup_tab(requested_url, placement, window, cx);
                        });
                    })
                    .detach();
            },
        )
    }

    fn browser_page_metadata_handler(
        &self,
        tab_id: BrowserTabId,
        cx: &mut gpui::Context<Self>,
    ) -> cef::BrowserPageMetadataHandler {
        let app = cx.entity().downgrade();
        let async_cx = cx.to_async();
        let foreground = cx.foreground_executor().clone();
        let project_epoch = self.browser_tabs_project_epoch;

        Rc::new(move |event: cef::BrowserPageMetadataEvent| {
            let app = app.clone();
            let mut async_cx = async_cx.clone();
            foreground
                .spawn(async move {
                    let _ = app.update_in(&mut async_cx, |this, window, cx| {
                        if this.browser_tabs_project_epoch != project_epoch {
                            return;
                        }
                        this.handle_browser_page_metadata_event(tab_id, event, window, cx);
                    });
                })
                .detach();
        })
    }

    fn browser_media_access_handler(
        &self,
        tab_id: BrowserTabId,
        profile_id: BrowserProfileId,
        cx: &mut gpui::Context<Self>,
    ) -> cef::BrowserMediaAccessHandler {
        let app = cx.entity().downgrade();
        let async_cx = cx.to_async();
        let foreground = cx.foreground_executor().clone();
        let project_epoch = self.browser_tabs_project_epoch;

        Rc::new(move |request: cef::BrowserMediaAccessRequest| {
            let app = app.clone();
            let mut async_cx = async_cx.clone();
            foreground
                .spawn(async move {
                    /*
                    An unanswered request cancels itself when dropped, so a
                    stale project epoch or a gone app entity releases the
                    page's `getUserMedia()` promise instead of hanging it.
                    */
                    let _ = app.update(&mut async_cx, |this, cx| {
                        if this.browser_tabs_project_epoch != project_epoch {
                            return;
                        }
                        this.handle_browser_media_access_request(tab_id, profile_id, request, cx);
                    });
                })
                .detach();
        })
    }

    fn handle_browser_media_access_request(
        &mut self,
        tab_id: BrowserTabId,
        profile_id: BrowserProfileId,
        request: cef::BrowserMediaAccessRequest,
        cx: &mut gpui::Context<Self>,
    ) {
        let kinds = request.kinds();
        let Some(origin) = gpui_browser_media_permission_origin(request.requesting_origin()) else {
            request.deny();
            return;
        };
        let decision = self
            .browser_media_permission_decisions
            .decision(profile_id, &origin);
        let undecided = decision.undecided(kinds);
        if undecided.is_empty() {
            request.allow(decision.granted(kinds));
            return;
        }

        self.browser_media_permission_prompts
            .entry(tab_id)
            .or_default()
            .push_back(GpuiBrowserMediaPermissionPrompt {
                profile_id,
                origin,
                requested: kinds,
                pending: undecided,
                request,
            });
        cx.notify();
    }

    fn resolve_browser_media_permission_prompt(
        &mut self,
        tab_id: BrowserTabId,
        allow: bool,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(queue) = self.browser_media_permission_prompts.get_mut(&tab_id) else {
            return;
        };
        let Some(prompt) = queue.pop_front() else {
            return;
        };
        if queue.is_empty() {
            self.browser_media_permission_prompts.remove(&tab_id);
        }

        /*
        Only the devices this prompt asked about are recorded, so answering a
        camera prompt never rewrites an earlier microphone answer. The grant
        then reads back the full stored decision, which is what lets a
        combined request use a device allowed by an earlier prompt.
        */
        self.browser_media_permission_decisions.record(
            prompt.profile_id,
            &prompt.origin,
            prompt.pending,
            allow,
        );
        persist_gpui_browser_media_permission_decisions(&self.browser_media_permission_decisions);
        let decision = self
            .browser_media_permission_decisions
            .decision(prompt.profile_id, &prompt.origin);
        prompt.request.allow(decision.granted(prompt.requested));
        // A page that asked twice before being answered (or that asked while
        // another prompt was up) is now covered by the stored answer, so those
        // queued prompts resolve silently instead of asking again.
        self.drain_decided_browser_media_permission_prompts(tab_id);
        cx.notify();
    }

    fn drain_decided_browser_media_permission_prompts(&mut self, tab_id: BrowserTabId) {
        let Some(queue) = self.browser_media_permission_prompts.get_mut(&tab_id) else {
            return;
        };
        let mut answered = Vec::new();
        while let Some(prompt) = queue.front() {
            let decision = self
                .browser_media_permission_decisions
                .decision(prompt.profile_id, &prompt.origin);
            if !decision.undecided(prompt.requested).is_empty() {
                break;
            }
            let Some(prompt) = queue.pop_front() else {
                break;
            };
            answered.push((prompt, decision));
        }
        if queue.is_empty() {
            self.browser_media_permission_prompts.remove(&tab_id);
        }
        for (prompt, decision) in answered {
            prompt.request.allow(decision.granted(prompt.requested));
        }
    }

    /// Drops (and therefore cancels) every pending media prompt for a tab.
    fn clear_browser_media_permission_prompts(&mut self, tab_id: BrowserTabId) {
        self.browser_media_permission_prompts.remove(&tab_id);
    }

    /// Navigation invalidates a pending prompt: the page that asked is gone,
    /// so its request is cancelled rather than left over the new document.
    fn clear_browser_media_permission_prompts_for_navigation(
        &mut self,
        tab_id: BrowserTabId,
        url: &str,
    ) {
        let origin = gpui_browser_media_permission_origin(url);
        let stale = self
            .browser_media_permission_prompts
            .get(&tab_id)
            .is_some_and(|queue| {
                queue
                    .front()
                    .is_some_and(|prompt| origin.as_deref() != Some(prompt.origin.as_str()))
            });
        if stale {
            self.clear_browser_media_permission_prompts(tab_id);
        }
    }

    fn browser_media_permission_prompt_for_tab(
        &self,
        tab_id: BrowserTabId,
    ) -> Option<&GpuiBrowserMediaPermissionPrompt> {
        self.browser_media_permission_prompts
            .get(&tab_id)
            .and_then(VecDeque::front)
    }

    /// Origin of the active tab that already has a stored microphone/camera
    /// answer, which is what makes the toolbar reset control appear.
    fn browser_media_permission_reset_target(
        &self,
        pane_id: BrowserPaneId,
    ) -> Option<(BrowserProfileId, String)> {
        let tab = self.browser_tabs.active_tab_for_pane(pane_id)?;
        let origin = gpui_browser_media_permission_origin(&tab.url)?;
        let decision = self
            .browser_media_permission_decisions
            .decision(tab.profile_id, &origin);
        (!decision.is_empty()).then_some((tab.profile_id, origin))
    }

    fn reset_browser_media_permissions_for_pane(
        &mut self,
        pane_id: BrowserPaneId,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some((profile_id, origin)) = self.browser_media_permission_reset_target(pane_id) else {
            return;
        };
        if !self
            .browser_media_permission_decisions
            .forget(profile_id, &origin)
        {
            return;
        }
        persist_gpui_browser_media_permission_decisions(&self.browser_media_permission_decisions);
        /*
        Chromium keeps the denied stream state on the live page, so the site
        only gets a fresh chance to ask after a reload.
        */
        if let Some(surface) = self.browser_surface_for_pane(pane_id) {
            surface.update(cx, |surface, _| surface.reload());
        }
        cx.notify();
    }

    fn sidebar_bridge_event_handler(
        &self,
        cx: &mut gpui::Context<Self>,
    ) -> cef::SidebarBridgeEventHandler {
        let app = cx.entity().downgrade();
        let async_cx = cx.to_async();
        let foreground = cx.foreground_executor().clone();

        Rc::new(move |event: cef::SidebarBridgeEvent| {
            let app = app.clone();
            let mut async_cx = async_cx.clone();
            foreground
                .spawn(async move {
                    let _ = app.update_in(&mut async_cx, |this, window, cx| {
                        this.receive_sidebar_bridge_event(event, window, cx);
                    });
                })
                .detach();
        })
    }

    /*
    CDXC:GPUITutorialVideoFullscreen 2026-08-18:
    The tutorial video should play fullscreen inside its own modal window. The
    page is a third-party document, so the app cannot call `requestFullscreen()`
    for it (Chromium requires a transient user activation that app-owned
    JavaScript never has); the host sends the player's own "f" shortcut as real
    input instead. The press waits a beat after main-frame load-end because the
    YouTube player installs its keyboard shortcuts after the page loads, and it
    is sent once because "f" toggles.
    */
    fn tutorial_video_page_load_end_handler(
        &self,
        cx: &mut gpui::Context<Self>,
    ) -> cef::PageLoadEndHandler {
        let app = cx.entity().downgrade();
        let async_cx = cx.to_async();
        let background = cx.background_executor().clone();
        let foreground = cx.foreground_executor().clone();

        Rc::new(move || {
            let app = app.clone();
            let mut async_cx = async_cx.clone();
            let background = background.clone();
            foreground
                .spawn(async move {
                    background
                        .timer(GPUI_TUTORIAL_VIDEO_FULLSCREEN_KEY_DELAY)
                        .await;
                    let _ = app.update(&mut async_cx, |this, cx| {
                        this.send_gpui_tutorial_video_fullscreen_key(cx);
                    });
                })
                .detach();
        })
    }

    fn send_gpui_tutorial_video_fullscreen_key(&mut self, cx: &mut gpui::Context<Self>) {
        let Some(handle) = self.app_modal_window else {
            return;
        };
        let _ = handle.update(cx, |host, _modal_window, cx| {
            host.send_tutorial_video_fullscreen_key(cx);
        });
    }

    fn app_modal_host_bridge_event_handler(
        &self,
        cx: &mut gpui::Context<Self>,
    ) -> cef::AppModalHostBridgeEventHandler {
        let app = cx.entity().downgrade();
        let async_cx = cx.to_async();
        let foreground = cx.foreground_executor().clone();

        Rc::new(move |event: cef::AppModalHostBridgeEvent| {
            let app = app.clone();
            let mut async_cx = async_cx.clone();
            foreground
                .spawn(async move {
                    let _ = app.update_in(&mut async_cx, |this, window, cx| {
                        this.receive_app_modal_host_bridge_event(event, window, cx);
                    });
                })
                .detach();
        })
    }

    /*
    CDXC:GPUISessionChatHostActions 2026-07-31:
    The chat CEF surface renders its own top-right [Terminal View][Agent
    Actions] cluster because a gpui-drawn overlay cannot paint above the
    native CEF view. Button clicks arrive over the already-installed
    app-modal-host bridge shim as `sessionChatHostAction` messages; this
    handler routes them into the same agent-action dispatch the terminal
    overlay uses.
    */
    fn session_chat_host_bridge_event_handler(
        &self,
        session_id: TerminalSessionId,
        cx: &mut gpui::Context<Self>,
    ) -> cef::AppModalHostBridgeEventHandler {
        let app = cx.entity().downgrade();
        let async_cx = cx.to_async();
        let foreground = cx.foreground_executor().clone();

        Rc::new(move |event: cef::AppModalHostBridgeEvent| {
            let cef::AppModalHostBridgeEvent::Message(payload) = event else {
                return;
            };
            let app = app.clone();
            let mut async_cx = async_cx.clone();
            foreground
                .spawn(async move {
                    let _ = app.update_in(&mut async_cx, |this, window, cx| {
                        this.receive_session_chat_host_action(session_id, &payload, window, cx);
                    });
                })
                .detach();
        })
    }

    fn receive_session_chat_host_action(
        &mut self,
        session_id: TerminalSessionId,
        payload: &str,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        use terminal_element::TerminalAgentActionRequest;

        let Ok(message) = serde_json::from_str::<serde_json::Value>(payload) else {
            return;
        };
        if message.get("type").and_then(serde_json::Value::as_str) != Some("sessionChatHostAction")
        {
            return;
        }
        let Some(action) = message.get("action").and_then(serde_json::Value::as_str) else {
            return;
        };
        if action == "composerReady" {
            if self.agents_chat_mode_sessions.contains(&session_id)
                && self.agents_chat_surfaces.contains_key(&session_id)
            {
                self.session_chat_composer_ready_sessions.insert(session_id);
            }
            self.complete_session_chat_composer_focus_handoff(session_id, window, cx);
            /*
            CDXC:SessionChatDraftHandoff 2026-08-18:
            A transferred draft also has to reach a chat surface the user is
            not looking at — the automatic switch runs over every newly
            eligible session, not just the focused one, and the focus handoff
            above deliberately does nothing for the rest.
            */
            if let Some(content) = self
                .pending_session_chat_composer_insert
                .remove(&session_id)
            {
                self.insert_prompt_into_session_chat(session_id, &content, cx);
            }
            return;
        }
        if action == "draftHandoffToTerminalComplete" {
            if !self.pending_session_chat_draft_handoffs.remove(&session_id) {
                return;
            }
            let content = message
                .get("content")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
                .to_string();
            if !content.is_empty() {
                // The terminal view already owns the pane while this
                // asynchronous copy finishes. Keep the cleared composer
                // snapshot until the exact terminal owner has remounted and
                // completed its focus handoff; inserting synchronously here
                // still races that remount.
                self.pending_session_terminal_composer_insert
                    .insert(session_id, content);
            }
            self.reconcile_agents_chat_surfaces(cx);
            return;
        }
        if action == "draftHandoffToTerminalFailed" {
            if self.pending_session_chat_draft_handoffs.remove(&session_id) {
                self.dispatch_gpui_app_modal_toast(
                    "warning",
                    "Draft handoff failed",
                    "The draft stayed in chat. Try switching again.",
                    cx,
                );
                self.reconcile_agents_chat_surfaces(cx);
            }
            return;
        }
        /*
        CDXC:GPUISessionChatAttachPicker 2026-08-02:
        The chat composer's attach button opens the same native open panel the
        terminal's Attach File or Folder action uses (files AND folders — a
        browser file input cannot offer folders or absolute paths). The answer
        rides back into the chat page through the app-owned script boundary as
        the fixed onSessionChatAttachmentsPicked callback with {requestId,
        paths}; cancel answers with empty paths so the page promise settles.
        */
        if action == "pickAttachments" {
            let request_id = message
                .get("requestId")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
                .to_string();
            self.request_session_chat_attachment_picks(session_id, request_id, cx);
            return;
        }
        /*
        CDXC:GPUISessionChatImageSave 2026-08-19:
        "Save image" in the chat's image overlay. A CEF page has no download
        handler here, so the bytes ride the bridge and Rust runs the native
        save panel and writes the file itself. The reply carries an error
        string only when the write actually failed: a cancelled panel is a
        completed request, not an error.
        */
        if action == "saveImage" {
            let request_id = message
                .get("requestId")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
                .to_string();
            let suggested_name = message
                .get("suggestedName")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("image.png")
                .to_string();
            let base64_data = message
                .get("base64Data")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
                .to_string();
            self.request_session_chat_image_save(
                session_id,
                request_id,
                suggested_name,
                base64_data,
                cx,
            );
            return;
        }
        /*
        CDXC:GPUISessionChatLinks 2026-08-03:
        Conversation links open in the app's own surfaces: a web URL goes to
        the integrated Browser while "Open links in embedded browser" is on
        (Shift+click, or that setting off, asks for the system default browser
        instead), and a file path goes to Docs or Code. Both leave the chat
        pane behind by design, so neither needs the focused-session routing
        below.
        */
        if action == "openLink" {
            let Some(url) = message.get("url").and_then(serde_json::Value::as_str) else {
                return;
            };
            let external = message
                .get("external")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false);
            self.open_session_chat_link(url, external, window, cx);
            return;
        }
        if action == "openFile" {
            let Some(path) = message.get("path").and_then(serde_json::Value::as_str) else {
                return;
            };
            self.open_session_chat_file(path, window, cx);
            return;
        }
        // The chat surface is only interactive as a rendered pane's active
        // session; focus that pane so the focused-session guard and the
        // "for focused session" modal openers resolve to this session.
        if self.focused_agents_or_companion_shell_session_id() != Some(session_id) {
            if self.active_mode.is_project_editor_mode() {
                // The chat surface is showing in the companion side pane;
                // focus its slot so focused-session guards resolve here.
                self.focus_project_editor_companion_terminal_session(
                    self.active_mode,
                    session_id,
                    window,
                    cx,
                );
            } else if let Some(pane_id) = self.agents_workspace.pane_id_for_session(session_id) {
                self.focus_agents_pane(pane_id, cx);
            }
        }
        // Prompt Editor and Attach File or Folder are separate TerminalView
        // events, not TerminalAgentActionRequest variants; both take explicit
        // targets and write to the warm PTY, so they work while the terminal
        // body is parked under the chat surface.
        if action == "promptEditor" || action == "attachPath" {
            let Some(runtime_session_id) = self
                .agents_gpui_engine_terminals
                .get(&session_id)
                .map(|record| record.runtime_session_id)
            else {
                return;
            };
            let target = GpuiEngineTerminalEventTarget::Agents(session_id);
            if action == "promptEditor" {
                self.handle_gpui_engine_prompt_editor_shortcut(target, runtime_session_id, cx);
            } else if let Some(attachment_target) =
                self.gpui_terminal_attachment_target_for_engine_target(target)
            {
                self.request_gpui_engine_terminal_attachment_paths(
                    attachment_target,
                    runtime_session_id,
                    cx,
                );
            }
            return;
        }
        if action == "terminalView" {
            self.handoff_agents_session_chat_mode(session_id, cx);
            return;
        }
        if action == "agentPickerTerminalView" {
            // Model selection deliberately uses a plain view switch: `/model`
            // must reach an empty CLI composer, while the chat draft remains
            // persisted for the return trip.
            self.toggle_agents_session_chat_mode(session_id, cx);
            self.dispatch_gpui_app_modal_toast(
                "info",
                "Please pick the model and effort in the CLI then switch back to the chat view",
                "",
                cx,
            );
            return;
        }
        let request = match action {
            "rename" => TerminalAgentActionRequest::Rename,
            "sleep" => TerminalAgentActionRequest::Sleep,
            "delayedActions" => TerminalAgentActionRequest::DelayedActions,
            "fork" => TerminalAgentActionRequest::Fork,
            "fullReload" => TerminalAgentActionRequest::FullReload,
            "exportTranscript" => TerminalAgentActionRequest::ExportTranscript,
            "stashPrompt" => TerminalAgentActionRequest::StashPrompt,
            "stashedPrompts" => TerminalAgentActionRequest::StashedPrompts,
            _ => return,
        };
        self.handle_gpui_engine_terminal_agent_action(
            GpuiEngineTerminalEventTarget::Agents(session_id),
            request,
            cx,
        );
    }

    fn request_session_chat_attachment_picks(
        &mut self,
        session_id: TerminalSessionId,
        request_id: String,
        cx: &mut gpui::Context<Self>,
    ) {
        let receiver = cx.prompt_for_paths(gpui::PathPromptOptions {
            files: true,
            directories: true,
            multiple: true,
            prompt: Some("Attach an Image, File, or Folder".into()),
        });
        cx.spawn(async move |this, cx| {
            let picked = match receiver.await {
                Ok(Ok(Some(paths))) => paths,
                _ => Vec::new(),
            };
            let _ = this.update(cx, |this, cx| {
                this.deliver_session_chat_attachment_picks(session_id, &request_id, picked, cx);
            });
        })
        .detach();
    }

    fn complete_session_chat_composer_focus_handoff(
        &mut self,
        session_id: TerminalSessionId,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        if self.pending_session_chat_composer_focus != Some(session_id) {
            return;
        }
        self.pending_session_chat_composer_focus = None;
        if !self.agents_chat_mode_sessions.contains(&session_id)
            || self.focused_agents_or_companion_shell_session_id() != Some(session_id)
        {
            return;
        }
        let Some(surface) = self.agents_chat_surfaces.get(&session_id).cloned() else {
            return;
        };
        let focus_handle = surface.read(cx).focus_handle.clone();
        focus_handle.focus(window, cx);
        surface.update(cx, |surface, _| {
            surface.focus();
            surface.execute_app_owned_script(
                "(function(){var ns=window.ghostexGpui;if(ns&&typeof ns.onSessionChatFocusComposerRequested==='function'){ns.onSessionChatFocusComposerRequested();}})(); undefined;",
            );
        });
        if let Some(content) = self
            .pending_session_chat_composer_insert
            .remove(&session_id)
        {
            let _ = self.insert_prompt_into_session_chat(session_id, &content, cx);
        }
    }

    fn drain_pending_session_chat_composer_focus_handoff(
        &mut self,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(session_id) = self.pending_session_chat_composer_focus else {
            return;
        };
        if self
            .session_chat_composer_ready_sessions
            .contains(&session_id)
        {
            self.complete_session_chat_composer_focus_handoff(session_id, window, cx);
        }
    }

    fn request_session_chat_image_save(
        &mut self,
        session_id: TerminalSessionId,
        request_id: String,
        suggested_name: String,
        base64_data: String,
        cx: &mut gpui::Context<Self>,
    ) {
        let bytes = match BASE64_STANDARD.decode(base64_data.as_bytes()) {
            Ok(bytes) => bytes,
            Err(error) => {
                support_logs::append(
                    support_logs::GpuiSupportLog::AppModal,
                    "gpui.sessionChat.imageSaveFailed",
                    serde_json::json!({ "error": error.to_string(), "stage": "decode" }),
                );
                self.deliver_session_chat_image_save(
                    session_id,
                    &request_id,
                    Some("The image bytes could not be read."),
                    cx,
                );
                return;
            }
        };
        // A file name, never a path: the page supplies it, and the panel's
        // directory is ours to choose.
        let file_name = Path::new(&suggested_name)
            .file_name()
            .map(|name| name.to_string_lossy().to_string())
            .filter(|name| !name.is_empty())
            .unwrap_or_else(|| "image.png".to_string());
        // Downloads is where a saved picture belongs by default; the panel lets
        // the user go anywhere else from there.
        let home = home_dir();
        let downloads = home.join("Downloads");
        let directory = if downloads.is_dir() { downloads } else { home };
        let receiver = cx.prompt_for_new_path(&directory, Some(file_name.as_str()));
        cx.spawn(async move |this, cx| {
            let destination = match receiver.await {
                Ok(Ok(Some(path))) => path,
                // Cancelled, or the panel could not open: nothing was written
                // and the panel already told the user. Settle the page promise.
                _ => {
                    let _ = this.update(cx, |this, cx| {
                        this.deliver_session_chat_image_save(session_id, &request_id, None, cx);
                    });
                    return;
                }
            };
            let error = match std::fs::write(&destination, &bytes) {
                Ok(()) => None,
                Err(error) => {
                    support_logs::append(
                        support_logs::GpuiSupportLog::AppModal,
                        "gpui.sessionChat.imageSaveFailed",
                        serde_json::json!({
                            "error": error.to_string(),
                            "path": destination.display().to_string(),
                            "stage": "write",
                        }),
                    );
                    Some("The image could not be written.")
                }
            };
            let _ = this.update(cx, |this, cx| {
                this.deliver_session_chat_image_save(session_id, &request_id, error, cx);
            });
        })
        .detach();
    }

    fn deliver_session_chat_image_save(
        &mut self,
        session_id: TerminalSessionId,
        request_id: &str,
        error: Option<&str>,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(surface) = self.agents_chat_surfaces.get(&session_id).cloned() else {
            return;
        };
        let payload = serde_json::json!({
            "error": error,
            "requestId": request_id,
        });
        let literal = payload
            .to_string()
            .replace('\u{2028}', "\\u2028")
            .replace('\u{2029}', "\\u2029");
        let script = format!(
            "(function(){{var ns=window.ghostexGpui;if(ns&&typeof ns.onSessionChatImageSaved==='function'){{ns.onSessionChatImageSaved({literal});}}}})(); undefined;"
        );
        surface.update(cx, |surface, _| {
            surface.execute_app_owned_script(&script);
        });
    }

    fn deliver_session_chat_attachment_picks(
        &mut self,
        session_id: TerminalSessionId,
        request_id: &str,
        paths: Vec<PathBuf>,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(surface) = self.agents_chat_surfaces.get(&session_id).cloned() else {
            return;
        };
        let payload = serde_json::json!({
            "requestId": request_id,
            "paths": paths
                .iter()
                .map(|path| path.to_string_lossy().to_string())
                .collect::<Vec<_>>(),
        });
        // JSON is a valid JS literal except for U+2028/U+2029; escape them so
        // a pathological file name cannot break the generated script.
        let literal = payload
            .to_string()
            .replace('\u{2028}', "\\u2028")
            .replace('\u{2029}', "\\u2029");
        let script = format!(
            "(function(){{var ns=window.ghostexGpui;if(ns&&typeof ns.onSessionChatAttachmentsPicked==='function'){{ns.onSessionChatAttachmentsPicked({literal});}}}})(); undefined;"
        );
        surface.update(cx, |surface, _| {
            surface.execute_app_owned_script(&script);
        });
    }

    fn request_session_chat_stash_prompt(
        &mut self,
        session_id: TerminalSessionId,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(surface) = self.agents_chat_surfaces.get(&session_id).cloned() else {
            return;
        };
        surface.update(cx, |surface, _| {
            surface.execute_app_owned_script(
                "(function(){var ns=window.ghostexGpui;if(ns&&typeof ns.onSessionChatStashPromptRequested==='function'){ns.onSessionChatStashPromptRequested();}})(); undefined;",
            );
        });
    }

    fn request_session_chat_handoff_to_terminal(
        &mut self,
        session_id: TerminalSessionId,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:SessionChatViewSwitch 2026-08-21:
        A view switch is unconditional UI state, not the success result of a
        draft-copy handshake. Ask a ready chat composer to copy its draft in
        the background, retain that hidden CEF surface until it answers, and
        show the terminal immediately. If the bridge is not ready, the draft
        remains in the chat composer's per-session storage for the return trip.
        */
        if self
            .session_chat_composer_ready_sessions
            .contains(&session_id)
            && self.pending_session_chat_draft_handoffs.insert(session_id)
            && let Some(surface) = self.agents_chat_surfaces.get(&session_id).cloned()
        {
            surface.update(cx, |surface, _| {
                surface.execute_app_owned_script(
                    "(function(){var ns=window.ghostexGpui;if(ns&&typeof ns.onSessionChatHandoffToTerminalRequested==='function'){ns.onSessionChatHandoffToTerminalRequested();}})(); undefined;",
                );
            });
        }
        self.toggle_agents_session_chat_mode(session_id, cx);
    }

    fn insert_prompt_into_session_chat(
        &mut self,
        session_id: TerminalSessionId,
        content: &str,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        let Some(surface) = self.agents_chat_surfaces.get(&session_id).cloned() else {
            return false;
        };
        let literal = serde_json::json!({ "content": content })
            .to_string()
            .replace('\u{2028}', "\\u2028")
            .replace('\u{2029}', "\\u2029");
        let script = format!(
            "(function(){{var ns=window.ghostexGpui;if(ns&&typeof ns.onSessionChatInsertPromptRequested==='function'){{ns.onSessionChatInsertPromptRequested({literal});}}}})(); undefined;"
        );
        surface.update(cx, |surface, _| {
            surface.execute_app_owned_script(&script);
        });
        true
    }

    /*
    CDXC:GPUISessionChatLinks 2026-08-03:
    A web link in the conversation opens where the reader already is: the
    integrated Browser workarea, through the same renderer-open path as
    `ghostex browser open` (same-origin reuse, so re-clicking a dev-server URL
    does not multiply tabs). Shift+click is the explicit escape hatch to the OS
    browser and takes the http/https-only external opener.

    CDXC:GPUISessionChatLinks 2026-08-18:
    Chat web links answer to the same "Open links in embedded browser" setting
    as Command-clicked terminal links, so a single switch decides where every
    agent-sent web link lands. With that setting off, an ordinary click leaves
    for the system default browser exactly like Shift+click already does.
    */
    fn open_session_chat_link(
        &mut self,
        url: &str,
        external: bool,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        if url.chars().count() > GPUI_SIDEBAR_OPEN_BROWSER_URL_MAX_CHARS {
            return;
        }
        let open_in_app =
            shared_settings::shared_sidebar_settings_snapshot().web_links_open_in_app();
        if external || !open_in_app {
            if let Some(url) = normalize_address(url) {
                let _ = gpui_open_external_http_url(&url);
            }
            return;
        }
        self.open_browser_url_from_renderer_command(
            GpuiSidebarOpenBrowserUrlMessage {
                url: url.to_string(),
                reuse: GpuiBrowserRendererOpenReuse::Similar,
                from_quick_header: false,
                project_id: None,
            },
            window,
            cx,
        );
    }

    /*
    CDXC:GPUISessionChatLinks 2026-08-03:
    A file link opens in the workarea that can actually show it. Docs is a
    docs-scoped browser (the docs/ folder, configured extra Docs folders, and
    root Markdown/HTML/Excalidraw artifacts), so a Markdown/HTML/Excalidraw
    file inside that scope goes to Docs and everything else — including a .md
    that lives outside it — goes to Code, which roots on the whole project.
    Paths are resolved against the active project so a relative path an agent
    quoted works the same as an absolute one.
    */
    fn open_session_chat_file(
        &mut self,
        path: &str,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        let trimmed = path.trim();
        if trimmed.is_empty() || trimmed.chars().count() > GPUI_PROJECT_CONTRACT_STRING_MAX_CHARS {
            return;
        }
        let Some(project_root) = self
            .latest_sidebar_project_snapshot
            .as_ref()
            .and_then(|snapshot| snapshot.in_memory_project_path.clone())
        else {
            self.report_session_chat_file_open_failure("No project is active in this window.", cx);
            return;
        };
        // One stat of a path the reader just clicked; no directory walk, so it
        // stays on the caller's thread like the other click handlers here.
        let candidate = if Path::new(trimmed).is_absolute() {
            PathBuf::from(trimmed)
        } else {
            project_root.join(trimmed)
        };
        let (Ok(file_path), Ok(root)) = (
            fs::canonicalize(&candidate),
            fs::canonicalize(&project_root),
        ) else {
            self.report_session_chat_file_open_failure(
                "That file is not available on this machine.",
                cx,
            );
            return;
        };
        if !fs::metadata(&file_path).is_ok_and(|metadata| metadata.is_file()) {
            self.report_session_chat_file_open_failure("That path is not a file.", cx);
            return;
        }
        let docs_relative_path = file_path
            .strip_prefix(&root)
            .ok()
            .map(|relative| relative.to_string_lossy().replace('\\', "/"))
            .filter(|relative| {
                let docs_folders = gpui_manage_additional_docs_folders_text(
                    &self.sidebar_runtime_settings_snapshot,
                );
                session_chat_file_opens_in_docs(relative, &docs_folders)
            });
        if let Some(relative_path) = docs_relative_path {
            if gpui_titlebar_mode_hidden_from_settings(TitlebarMode::Manage) {
                self.copy_path_for_disabled_project_workarea(trimmed, "Docs", cx);
                return;
            }
            self.report_session_chat_file_opening("Docs view", &file_path, cx);
            self.pending_docs_file_open = Some(relative_path);
            self.switch_workarea_from_hotkey(TitlebarMode::Manage, window, cx);
            self.mark_project_editor_mode_awake(TitlebarMode::Manage, cx);
            self.focus_project_editor_surface(TitlebarMode::Manage, window, cx);
            if !self.deliver_pending_docs_file_open(cx) {
                self.schedule_pending_docs_file_open_delivery(cx);
            }
            return;
        }
        if gpui_titlebar_mode_hidden_from_settings(TitlebarMode::Source)
            || !self.titlebar_mode_available(TitlebarMode::Source)
        {
            /*
            CDXC:GPUTitlebarAvailability 2026-08-20:
            Source is also unavailable for remote projects, where switching
            would be refused by set_active_mode and leave this route silently
            dead. Fall back to the same copy-the-path affordance the hidden-tab
            case uses instead of parking on an unreachable workarea.
            */
            self.copy_path_for_disabled_project_workarea(trimmed, "Code", cx);
            return;
        }
        /*
        Code view is an on-demand component, so it is not always installed.
        Switching to Source without it only parks the reader on the component
        installer prompt with the file still unopened, so reveal the file in the
        OS file manager instead and let them open it with what they do have.
        */
        if let Some(reason) = self.embedded_code_editor_unavailable_reason() {
            self.reveal_session_chat_file_in_file_manager(&file_path, reason, cx);
            return;
        }
        self.report_session_chat_file_opening("Code view", &file_path, cx);
        self.pending_source_file_open = Some(PendingSourceFileOpen {
            file_path,
            project_path: root,
        });
        self.switch_workarea_from_hotkey(TitlebarMode::Source, window, cx);
        self.mark_project_editor_mode_awake(TitlebarMode::Source, cx);
        self.focus_project_editor_surface(TitlebarMode::Source, window, cx);
    }

    fn copy_path_for_disabled_project_workarea(
        &mut self,
        path: &str,
        plugin_name: &str,
        cx: &mut gpui::Context<Self>,
    ) {
        cx.write_to_clipboard(ClipboardItem::new_string(path.to_string()));
        self.upsert_gpui_app_toast(
            GpuiAppToast {
                id: format!(
                    "gpui-disabled-{}-file-path-copied",
                    plugin_name.to_ascii_lowercase()
                ),
                level: GpuiAppToastLevel::from_raw(Some("success")),
                title: "Copied to Clipboard!".to_string(),
                description: Some(format!("({plugin_name} plugin is disabled)")),
                loading: false,
                persistent: false,
                duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                epoch: 0,
            },
            cx,
        );
    }

    /** Main-window toast for a chat file link that cannot be opened. */
    fn report_session_chat_file_open_failure(
        &mut self,
        description: &str,
        cx: &mut gpui::Context<Self>,
    ) {
        self.upsert_gpui_app_toast(
            GpuiAppToast {
                id: "gpui-session-chat-file-open-failed".to_string(),
                level: GpuiAppToastLevel::from_raw(Some("warning")),
                title: "Could not open the file".to_string(),
                description: Some(description.to_string()),
                loading: false,
                persistent: false,
                duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                epoch: 0,
            },
            cx,
        );
    }

    /**
    Main-window toast naming where a clicked chat file link is going. The
    workarea switch takes the reader off the chat pane and Code/Docs can take a
    moment to show the file, so the toast is what tells them the click landed.
    */
    fn report_session_chat_file_opening(
        &mut self,
        destination: &str,
        file_path: &Path,
        cx: &mut gpui::Context<Self>,
    ) {
        self.upsert_gpui_app_toast(
            GpuiAppToast {
                id: "gpui-session-chat-file-opening".to_string(),
                level: GpuiAppToastLevel::from_raw(None),
                title: format!("Opening file in {destination}"),
                description: gpui_path_file_name_label(file_path),
                loading: false,
                persistent: false,
                duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                epoch: 0,
            },
            cx,
        );
    }

    /** Chat file link on a machine with no usable Code view: reveal it instead. */
    fn reveal_session_chat_file_in_file_manager(
        &mut self,
        file_path: &Path,
        reason: &str,
        cx: &mut gpui::Context<Self>,
    ) {
        if let Err(message) = gpui_reveal_path_in_finder(file_path) {
            self.report_session_chat_file_open_failure(&message, cx);
            return;
        }
        self.upsert_gpui_app_toast(
            GpuiAppToast {
                id: "gpui-session-chat-file-opening".to_string(),
                level: GpuiAppToastLevel::from_raw(None),
                title: format!("Opening file in {GPUI_FILE_MANAGER_NAME}"),
                description: Some(reason.to_string()),
                loading: false,
                persistent: false,
                duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                epoch: 0,
            },
            cx,
        );
    }

    /**
    `None` when the bundled code-server component can actually open a file right
    now, otherwise the reason to show the reader. This is the same availability
    read the Source workarea launches on, so a `None` here means the workarea
    switch ends on the file rather than on the component installer prompt.
    */
    fn embedded_code_editor_unavailable_reason(&self) -> Option<&'static str> {
        let Some(target) = self
            .latest_sidebar_project_snapshot
            .as_ref()
            .and_then(|snapshot| self.source_code_server_runtime_target(snapshot))
        else {
            return Some("Code view is not available for this project.");
        };
        match source_code_server_runtime_availability(&target) {
            SourceCodeServerRuntimeAvailability::Available => None,
            SourceCodeServerRuntimeAvailability::InstallRequired => {
                Some("Code view is not installed on this machine.")
            }
            SourceCodeServerRuntimeAvailability::Failed(_) => {
                Some("Code view is unavailable on this machine.")
            }
        }
    }

    /**
    Hands the pending Docs path to the Manage page. The surface may not exist
    yet (the mode was just switched) and the page may still be loading, so the
    request stays pending until the script lands and the injected script itself
    waits for the page's own open hook, the same retry shape the Manage bridge
    shim uses.
    */
    fn deliver_pending_docs_file_open(&mut self, cx: &mut gpui::Context<Self>) -> bool {
        let Some(relative_path) = self.pending_docs_file_open.clone() else {
            return false;
        };
        let Some(surface) = self
            .project_workarea_runtime_cef_surfaces
            .get(&ProjectWorkareaCefSurfaceSlotKey::Manage)
            .map(|owned_surface| owned_surface.surface.clone())
        else {
            return false;
        };
        // JSON is a valid JS literal except for U+2028/U+2029; escape them so
        // a pathological file name cannot break the generated script.
        let literal = serde_json::Value::String(relative_path)
            .to_string()
            .replace('\u{2028}', "\\u2028")
            .replace('\u{2029}', "\\u2029");
        let script = format!(
            "(function(){{var p={literal};var a=0;var send=function(){{var open=window.ghostexOpenDocsFile;if(typeof open==='function'){{open(p);return;}}if(++a<250){{setTimeout(send,20);}}}};send();}})(); undefined;"
        );
        let dispatched = surface.update(cx, |surface, _| surface.execute_app_owned_script(&script));
        if dispatched {
            self.pending_docs_file_open = None;
        }
        dispatched
    }

    /**
    Docs may need a moment before it can take the request: the mode switch
    creates the surface, and CEF has no main frame to run the script in until
    the page commits. Surface reconciliation is event-driven, so poll briefly
    instead of waiting for the next unrelated event, and drop the request if
    Docs never comes up.
    */
    fn schedule_pending_docs_file_open_delivery(&mut self, cx: &mut gpui::Context<Self>) {
        cx.spawn(async move |this, cx| {
            for _ in 0..PENDING_DOCS_FILE_OPEN_MAX_ATTEMPTS {
                cx.background_executor()
                    .timer(PENDING_DOCS_FILE_OPEN_RETRY_INTERVAL)
                    .await;
                match this.update(cx, |this, cx| this.deliver_pending_docs_file_open(cx)) {
                    Ok(false) => {}
                    // Delivered, or the app is gone.
                    _ => return,
                }
            }
            let _ = this.update(cx, |this, _| {
                this.pending_docs_file_open = None;
            });
        })
        .detach();
    }

    fn open_gpui_app_modal_from_titlebar(
        &mut self,
        modal: GpuiAppModalKind,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUITitlebarAppModalHost 2026-06-24-10:42:
        GPUI titlebar Settings, Hotkeys, and Command Palette actions must open the shared React app-modal host in a real GPUI CEF window. The route reuses the macOS modal ids and latest Settings-compatible sidebar hydrate, with no duplicated React modal UI, WebKit/WKWebView, transparent overlay, hidden hit-test region, synthetic mouse routing, or generic fallback surface.

        CDXC:GPUIPreviousSessionsModal 2026-06-24-11:53:
        Previous Sessions joins the same GPUI-owned CEF app-modal window path as Settings, Hotkeys, and Command Palette. The titlebar route must open the shared React modal component directly and let its gxserver-backed query resolve through sidebarCommand responses, not duplicated GPUI UI, overlays, hit-test routing, or stored hydrate rewrites.

        CDXC:GPUIDaemonSessionsModal 2026-06-24-12:00:
        Running Sessions uses the same shared React daemonSessions modal in the GPUI-owned CEF app-modal host. Open-time daemon state is delivered as a transient sidebarState message so the Settings hydrate snapshot remains the stored modal host snapshot and gxserver unavailability renders honestly instead of a placeholder inventory.

        CDXC:GxserverAppUserData 2026-06-24-13:30:
        Pinned Prompts and Scratch Pad open through this same React modal host and must receive real persisted gxserver app-user-data on every route. Keep prompt/note content inside the authenticated hydrate payload only; do not log it or create duplicate GPUI modal UI.

        CDXC:GPUISettingsEntryModals 2026-06-24-12:22:
        Configure Agents, Configure Actions, and Open Targets are Settings-modal entry points in the shared React host. GPUI must preserve their modal ids, attach the latest Settings-compatible sidebar hydrate, and reuse this production CEF app-modal route instead of adding duplicate React UI, stubs, fallback routing, overlays, or hidden hit regions.

        CDXC:GPUIAgentsHubModal 2026-06-24-12:26:
        Agents Hub opens through this same CEF app-modal host so command-palette bridge requests and titlebar menu actions present the existing shared React modal. Its catalog/content are separate sidebarCommand responses and should not be bundled into the open message.
        */
        let sidebar_state_message = self.gpui_app_modal_sidebar_state_message_for_open(modal, cx);
        let mut open_message = modal.open_message();
        if modal.requires_sidebar_state() {
            open_message["latestSidebarStateMessage"] = sidebar_state_message.clone();
        }

        self.open_gpui_app_modal_window(
            modal,
            open_message,
            sidebar_state_message,
            Some(window),
            cx,
        );
    }

    fn gpui_command_delayed_send_open_message(
        &self,
        session_id: CommandSessionId,
        title: &str,
    ) -> serde_json::Value {
        let mut message = serde_json::json!({
            "closeAfterDoneActive": self
                .command_pane
                .session(session_id)
                .is_some_and(|session| session.close_after_done_armed),
            "modal": GpuiAppModalKind::DelayedSend.modal_id(),
            "sessionId": gpui_command_session_external_id(session_id),
            "title": title,
            "type": "open",
        });
        if let Some(timer) = self.command_delayed_send_timers.get(&session_id).copied() {
            let remaining_ms = timer.remaining_ms(SystemTime::now());
            message["delayedSendDeadlineAt"] =
                serde_json::json!(gpui_iso8601_utc(timer.deadline_at));
            message["delayedSendRemainingLabel"] =
                serde_json::json!(gpui_command_delayed_send_countdown_label(remaining_ms));
        }
        message
    }

    fn gpui_command_delayed_send_remaining_label_for_session(
        &self,
        session_id: CommandSessionId,
    ) -> Option<String> {
        self.command_delayed_send_timers
            .get(&session_id)
            .copied()
            .and_then(|timer| {
                gpui_command_delayed_send_body_badge_label(Some(timer), SystemTime::now())
            })
    }

    fn command_pane_tab_exists(
        &self,
        group_id: CommandPaneGroupId,
        session_id: CommandSessionId,
    ) -> bool {
        self.command_pane
            .find_leaf(group_id)
            .is_some_and(|leaf| leaf.tab_group.has_session(session_id))
            && self.command_pane.session(session_id).is_some()
    }

    fn open_gpui_delayed_send_modal_for_command_pane_tab(
        &mut self,
        group_id: CommandPaneGroupId,
        session_id: CommandSessionId,
        window: &Window,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        /*
        CDXC:GPUICommandTabContextMenu 2026-06-25-17:37:
        Delayed Send from a clicked command tab is session-scoped like native, but GPUI can only execute the later Return through a visible mounted command body. Selecting, expanding, and waking the clicked tab before opening the modal is the normal-layout equivalent of targeting that native command session.
        */
        if !self.command_pane_tab_exists(group_id, session_id) {
            return false;
        }
        let expand_pane = !self.command_pane.is_expanded();
        if !self.select_command_pane_tab(group_id, session_id, expand_pane, window, cx) {
            return false;
        }
        if self
            .command_pane
            .session(session_id)
            .is_some_and(|session| session.is_sleeping)
        {
            self.wake_command_pane_session(group_id, session_id, cx);
        }
        let Some(title) = self
            .command_pane
            .session(session_id)
            .map(|session| session.title.clone())
        else {
            return false;
        };
        let modal = GpuiAppModalKind::DelayedSend;
        let sidebar_state_message = self.gpui_app_modal_sidebar_state_message_for_open(modal, cx);
        let open_message = self.gpui_command_delayed_send_open_message(session_id, &title);
        self.open_gpui_app_modal_window(modal, open_message, sidebar_state_message, None, cx);
        true
    }

    fn focus_command_pane_tab_for_context_session_action(
        &mut self,
        action: CommandPaneTabSessionAction,
        group_id: CommandPaneGroupId,
        session_id: CommandSessionId,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        /*
        CDXC:GPUICommandTabContextMenu 2026-06-25-18:33:
        Legacy clicked-tab action handlers focus the clicked terminal before Rename and Close After Done dispatch. Select and focus the clicked GPUI command tab without expanding a collapsed strip so the action target becomes the command-pane focus while left-click remains the only hidden-open gesture.

        CDXC:GPUICommandAttention 2026-06-25-19:58:
        Primary clicked-tab context actions use that same focus path, so they acknowledge only the clicked Attention command session before opening Rename or toggling Close After Done.

        CDXC:GPUICommandTabContextMenu 2026-06-27-01:55:
        Command-tab right-click no longer exposes these retained handlers because native command-panel payloads are panel-only. Keep the helper for non-menu command-tab dispatch paths without reintroducing visible primary menu rows.
        */
        if command_pane_tab_context_session_action_focus_policy(action)
            != CommandPaneTabContextFocusPolicy::SelectAndFocus
        {
            return false;
        }
        if !self.command_pane_tab_exists(group_id, session_id)
            || !self
                .command_pane
                .select_session_in_group(group_id, session_id)
        {
            return false;
        }

        self.command_pane
            .acknowledge_attention_for_session_activation(session_id);
        self.focus_command_pane();
        self.scroll_command_group_active_tab(group_id);
        self.scroll_focused_command_active_tab();
        self.persist_shell_layout_state();
        self.refresh_sidebar_command_pane_sessions_if_changed(cx);
        cx.notify();
        true
    }

    /// Cmd+R with a focused Agents-view or companion-pane terminal renames
    /// the focused mapped gxserver session through the shared Rename Session
    /// modal, matching macOS `promptRenameFocusedNativeHotkeySession`.
    /// Unmapped local placeholder tabs have no gxserver identity to rename
    /// and no-op.
    fn open_gpui_rename_session_modal_for_focused_agents_session(
        &mut self,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        let Some(shell_session_id) = self.focused_agents_or_companion_shell_session_id() else {
            return false;
        };
        let Some(key) = self
            .local_workspace_session_mappings
            .iter()
            .find_map(|(key, mapped)| (*mapped == shell_session_id).then(|| key.clone()))
        else {
            return false;
        };
        let Some(title) = self
            .agents_workspace
            .session(shell_session_id)
            .map(|session| session.title.clone())
        else {
            return false;
        };
        let modal = GpuiAppModalKind::RenameSession;
        let sidebar_state_message = self.gpui_app_modal_sidebar_state_message_for_open(modal, cx);
        let mut open_message = serde_json::json!({
            "initialTitle": title,
            "modal": modal.modal_id(),
            "sessionId": gpui_combined_presentation_session_id(
                &key.project_id,
                &key.session_id,
            ),
            "type": "open",
        });
        if modal.requires_sidebar_state() {
            open_message["latestSidebarStateMessage"] = sidebar_state_message.clone();
        }
        self.open_gpui_app_modal_window(modal, open_message, sidebar_state_message, None, cx);
        true
    }

